  "flow": [
    {
      "slide": 1,
      "does": "Recall encoding, storage and retrieval",
      "look_at": {"kind": "none", "shows": null},
      "teaches": []
    },
    {
      "slide": 2,
      "does": "Introduce the approved objectives",
      "look_at": {"kind": "none", "shows": null},
      "teaches": []
    },
    {
      "slide": 3,
      "does": "Predict differences between memory stores",
      "look_at": {"kind": "none", "shows": null},
      "teaches": [1]
    },
    {
      "slide": 4,
      "does": "Teach coding, capacity and duration",
      "look_at": {"kind": "diagram", "shows": "A comparison table of the three stores"},
      "teaches": [1]
    },
    {
      "slide": 5,
      "does": "Explain transfers between stores",
      "look_at": {"kind": "diagram", "shows": "Attention, rehearsal and retrieval in the model"},
      "teaches": [2]
    },
    {
      "slide": 6,
      "does": "Model an explanation of remembering a number",
      "look_at": {"kind": "diagram", "shows": "A worked route through the three stores"},
      "teaches": [2]
    },
    {
      "slide": 7,
      "does": "Apply the same explanation independently",
      "look_at": {"kind": "none", "shows": null},
      "teaches": [1, 2]
    },
    {
      "slide": 8,
      "does": "Teach serial position evidence",
      "look_at": {"kind": "diagram", "shows": "Schematic immediate and delayed recall curves"},
      "teaches": [3]
    },
    {
      "slide": 9,
      "does": "Build a supported evaluation argument",
      "look_at": {"kind": "none", "shows": null},
      "teaches": [2, 3]
    },
    {
      "slide": 10,
      "does": "Correct the single-STM misconception using KF",
      "look_at": {"kind": "diagram", "shows": "KF's contrasting verbal recall performance"},
      "teaches": [3]
    },
    {
      "slide": 11,
      "does": "Check the scope of the KF challenge",
      "look_at": {"kind": "none", "shows": null},
      "teaches": [3]
    },
    {
      "slide": 12,
      "does": "Apply and weigh the model in a new situation",
      "look_at": {"kind": "none", "shows": null},
      "teaches": [1, 2, 3]
    }
  ],
  "title": {
    "template": "title",
    "heading": "The multi-store model of memory",
    "lead": "Recall: what do encoding, storage and retrieval mean?",
    "picture": null
  },
  "slides": [
    {
      "template": "discussion",
      "heading": "Make a prediction",
      "lead": "Would a fleeting sound, a number held for seconds and a childhood memory have the same coding, capacity and duration? Explain your prediction.",
      "picture": null
    },
    {
      "template": "big-visual",
      "heading": "Three stores: Atkinson and Shiffrin (1968)",
      "lead": "Coding is the form of information; capacity is how much; duration is how long.",
      "figure": {
        "kind": "table",
        "shows": "Typical AQA descriptions of the three memory stores; values are approximate.",
        "alt": "The sensory register, STM and LTM differ in their coding, capacity and duration.",
        "title": null,
        "header": ["Store", "Coding", "Capacity", "Duration"],
        "rows": [
          ["Sensory register", "Sense-specific", "Very large", "Usually <0.5 seconds"],
          ["Short-term (STM)", "Mainly acoustic", "7 ± 2 items", "About 18–30 seconds"],
          ["Long-term (LTM)", "Mainly semantic", "Potentially unlimited", "Potentially lifelong"]
        ]
      }
    },
    {
      "template": "visual-text",
      "heading": "How information moves",
      "lead": "The model proposes separate stores linked by control processes.",
      "points": [
        "Attention selects sensory information for STM.",
        "Maintenance rehearsal keeps information in STM.",
        "Prolonged rehearsal transfers it to LTM; retrieval returns it to STM."
      ],
      "figure": {
        "kind": "flow",
        "shows": "Information enters the sensory register, moves to STM through attention and to LTM through prolonged rehearsal; retrieval returns it to STM.",
        "alt": "Sensory input enters the sensory register. Attention leads to STM, which has a rehearsal loop. Prolonged rehearsal leads to LTM; retrieval leads back to STM.",
        "title": null,
        "nodes": ["Sensory input", "Sensory register", "STM", "LTM"],
        "links": [
          {"from": 0, "to": 1, "label": null},
          {"from": 1, "to": 2, "label": "Attention"},
          {"from": 2, "to": 2, "label": "Maintenance rehearsal"},
          {"from": 2, "to": 3, "label": "Prolonged rehearsal"},
          {"from": 3, "to": 2, "label": "Retrieval"}
        ]
      }
    },
    {
      "template": "visual-text",
      "heading": "Worked example: a new phone number",
      "lead": "Amira hears a number, focuses on it, repeats it many times and recalls it next week.",
      "points": [
        "Attention selects the heard number for STM.",
        "Repetition maintains it in STM and, in this model, transfers it to LTM.",
        "Next week, retrieval brings it from LTM into STM."
      ],
      "figure": {
        "kind": "flow",
        "shows": "The phone-number example mapped onto the three memory stores.",
        "alt": "A heard number passes from sensory register to STM through attention, then to LTM through prolonged rehearsal, and back through retrieval.",
        "title": null,
        "nodes": ["Sensory register", "STM", "LTM"],
        "links": [
          {"from": 0, "to": 1, "label": "Attention"},
          {"from": 1, "to": 1, "label": "Repetition"},
          {"from": 1, "to": 2, "label": "Prolonged rehearsal"},
          {"from": 2, "to": 1, "label": "Retrieval"}
        ]
      }
    },
    {
      "template": "practice",
      "heading": "Your turn: a new access code",
      "questions": [
        "Leo hears an access code, focuses on it and repeats it many times. Explain its route into LTM.",
        "Leo recalls the code next week. Explain the transfer needed to use it.",
        "Leo stops repeating an unfamiliar code and is distracted for 40 seconds. Predict what happens and explain why."
      ],
      "instruction": "Write using store names and transfer processes.",
      "picture": null
    },
    {
      "template": "visual-text",
      "heading": "Glanzer and Cunitz (1966)",
      "lead": "Participants recalled word lists immediately or after a filled delay, including 30 seconds of counting.",
      "points": [
        "Immediate recall: early and late words were recalled best.",
        "After 30 seconds: the recency effect disappeared; primacy remained.",
        "MSM explanation: early words entered LTM; late words were still in STM."
      ],
      "figure": {
        "kind": "line-graph",
        "shows": "Schematic serial position curves, not original numerical data: immediate recall has primacy and recency; filled-delay recall retains primacy but loses recency.",
        "alt": "Immediate recall is high at the start and end of a list. After a filled delay, recall stays high at the start but not at the end.",
        "title": null,
        "x": {"label": "Position in word list", "min": 1, "max": 10, "step": 1},
        "y": {"label": "Recall", "min": 0, "max": 10, "step": 2},
        "y2": null,
        "qualitative": true,
        "series": [
          {
            "label": "Immediate",
            "points": [[1, 9], [2, 7], [3, 5], [4, 3], [5, 3], [6, 3], [7, 4], [8, 5], [9, 7], [10, 9]],
            "style": "line",
            "axis": "left"
          },
          {
            "label": "30-second delay",
            "points": [[1, 9], [2, 7], [3, 5], [4, 3], [5, 3], [6, 3], [7, 3], [8, 3], [9, 3], [10, 3]],
            "style": "line",
            "axis": "left"
          }
        ],
        "segments": null,
        "annotations": null,
        "intervals": null
      }
    },
    {
      "template": "question-set",
      "heading": "What does the evidence establish?",
      "questions": [
        "Glanzer and Cunitz found that a 30-second counting delay removed recency but preserved primacy. Explain this using the MSM.",
        "Explain why this different effect on early and late words supports separate STM and LTM stores.",
        "A pupil says, “This proves every part of the MSM.” Assess that claim using the findings above."
      ],
      "instruction": "Build an argument: finding → explanation → judgement.",
      "picture": null
    },
    {
      "template": "visual-text",
      "heading": "Must STM be one single store?",
      "lead": "Shallice and Warrington (1970) studied KF, a patient with brain damage.",
      "points": [
        "KF's verbal STM was much poorer for heard than visually presented information.",
        "This challenges one unitary STM store: presentation modality mattered.",
        "It does not show that STM is absent, or disprove every part of the MSM."
      ],
      "figure": {
        "kind": "table",
        "shows": "A qualitative comparison of KF's verbal short-term recall by presentation modality.",
        "alt": "KF's short-term recall of heard verbal material was severely impaired; recall of visually presented verbal material was relatively better.",
        "title": null,
        "header": ["Input", "Verbal STM"],
        "rows": [
          ["Heard", "Poor"],
          ["Seen", "Better"]
        ]
      }
    },
    {
      "template": "hinge",
      "heading": "Check the conclusion",
      "stem": "KF recalled seen verbal material better than heard material. Which conclusion is best?",
      "options": [
        "KF had no short-term memory at all.",
        "The idea of one unitary STM store is challenged.",
        "The existence of long-term memory is disproved.",
        "The MSM's rehearsal process is confirmed."
      ],
      "correct": 2
    },
    {
      "template": "practice",
      "heading": "Apply and weigh the model",
      "questions": [
        "A visitor hears a gate code once, repeats it until entering, then forgets it after a minute of conversation. Explain using coding, duration and rehearsal.",
        "The visitor remembers her childhood address immediately. Explain its storage and retrieval using the MSM.",
        "Stretch: a designer proposes one temporary memory system for all input. Weigh Glanzer and Cunitz's findings against KF when judging this proposal."
      ],
      "instruction": "Write independently. Make each explanation specific to the situation.",
      "picture": null
    }
  ]
}
